const units = ["ms", "s", "m", "h"] as const;
type Units = (typeof units)[number];
/**
 * 将指定单位的时间，转换为可读时间
 * @param time number
 * @param unit Units
 * @returns string
 */
export function timeToReadable(time: number, unit: Units = "ms"): string {
  const times = [1000, 60, 60, 24];

  time < 0 && (time = 0);
  let i = units.indexOf(unit);
  const result: string[] = [];

  // Convert the time to microseconds if it's not already
  while (i > 0) {
    time *= times[--i];
  }

  time = Math.floor(time / 1000);

  // Calculate hours, minutes and seconds
  const hours = Math.floor(time / 3600) || 0;
  time %= 3600;
  const minutes = Math.floor(time / 60) || 0;
  const seconds = Math.floor(time % 60) || 0;

  // Format time components to have two digits
  result.push(hours.toString().padStart(2, "0"));
  result.push(minutes.toString().padStart(2, "0"));
  result.push(seconds.toString().padStart(2, "0"));

  return result.join(":");
}

/**
 * 将比特转换为可读的大小
 * @param bytes Number
 * @returns string
 */
export function bytesToSize(bytes: number, fractionDigits = 2): string {
  if (!bytes) return "0KB";
  const sizes = ["B", "KB", "MB", "GB", "TB"];
  let i = Math.floor(Math.log(Number(bytes)) / Math.log(1024));
  if (i >= sizes.length) i = sizes.length - 1;
  return `${parseFloat((Number(bytes) / 1024 ** i).toFixed(fractionDigits))}${sizes[i]}`;
}
